import sys
import heapq

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        T_str = next(iterator)
    except StopIteration:
        return

    T = int(T_str)

    for _ in range(T):
        N = int(next(iterator))
        K = int(next(iterator))
        X = int(next(iterator))
        M = int(next(iterator))
        S = int(next(iterator))

        adj = [[] for _ in range(N + 1)]

        for _ in range(M):
            u = int(next(iterator))
            v = int(next(iterator))
            w = int(next(iterator))
            adj[u].append((v, w))
            adj[v].append((u, w))

        INF = float('inf')
        dist = [INF] * (N + 1)

        if S <= K:
            dist[S] = 0
            for i in range(1, K + 1):
                if i != S:
                    dist[i] = X
        else:
            dist[S] = 0

        pq = []

        if S <= K:
            for i in range(1, K + 1):
                 if i != S:
                     heapq.heappush(pq, (X, i))
        else:
            heapq.heappush(pq, (0, S))

        visited_old = [False] * (K + 1)
        processed_old = False

        while pq:
            d, u = heapq.heappop(pq)

            if d > dist[u]:
                continue

            if u <= K:
                if not visited_old[u]:
                    visited_old[u] = True
                    if not processed_old:
                        processed_old = True
                        for v in range(1, K + 1):
                            if v != u:
                                new_dist = d + X
                                if new_dist < dist[v]:
                                    dist[v] = new_dist
                                    heapq.heappush(pq, (new_dist, v))

            for v, w in adj[u]:
                new_dist = d + w
                if new_dist < dist[v]:
                    dist[v] = new_dist
                    heapq.heappush(pq, (new_dist, v))

        result = []
        for i in range(1, N + 1):
            result.append(str(dist[i]))

        print(" ".join(result))

if __name__ == "__main__":
    solve()
